class Solution {
    public int maxArea(int[] height) {
        int n = height.length;
        int maxArea = 0;

        for (int i = 0; i < n - 1; i++) {
            for (int j = i + 1; j < n; j++) {
                // 木桶效应：水的高度由两块板中较矮的那块决定
                int h = Math.min(height[i], height[j]);
                int area = h * (j - i);
                if (area > maxArea) maxArea = area;
            }
        }
        return maxArea;
    }
}

class Solution {
    public int maxArea(int[] height) {
        int n = height.length;
        int[] leftMax = new int[n];
        leftMax[0] = height[0];
        for (int i = 1; i < n; i++) {
            leftMax[i] = Math.max(leftMax[i - 1], height[i]);
        }

        int maxArea = 0;
        for (int j = 1; j < n; j++) {
            // j 左边有更高（或等高）的板，用它当右端点不可能更优
            if (height[j] <= leftMax[j - 1]) continue;
            for (int i = 0; i < j; i++) {
                int area = Math.min(height[i], height[j]) * (j - i);
                if (area > maxArea) maxArea = area;
            }
        }
        return maxArea;
    }
}

class Solution {
    public int maxArea(int[] height) {
        int left = 0, right = height.length - 1;
        int maxArea = 0;

        while (left < right) {
            int area = Math.min(height[left], height[right]) * (right - left);
            if (area > maxArea) maxArea = area;

            // 关键：移动较矮的一边。固定的那侧已被榨干，不可能得到更优解
            if (height[left] < height[right]) {
                left++;
            } else {
                right--;
            }
        }
        return maxArea;
    }
}
